import{_ as d,c as r,o as e,af as a}from"./chunks/framework.r60quYNK.js";const i=JSON.parse('{"title":"我的健身记录💪","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/11_my_exercise.md","filePath":"2_articles/11_my_exercise.md"}'),h={name:"2_articles/11_my_exercise.md"};function o(g,t,k,s,c,n){return e(),r("div",null,t[0]||(t[0]=[a('<h1 id="我的健身记录💪" tabindex="-1">我的健身记录💪 <a class="header-anchor" href="#我的健身记录💪" aria-label="Permalink to &quot;我的健身记录💪&quot;">​</a></h1><p><code>24年4月份</code>第一次接触健身，信誓旦旦的办了四个月的卡，啥也不懂就买了增肌粉，抱着练一休一，甚至练一休半月的惰性，给自己找了无数忙的理由，最后断断续续连一个月都没练下。</p><p><code>24年底</code>在上海实习的时候，感受到互联网算法庞大的压力，突然觉得自己应该要有一个好的身体去应对未来(<strong>以及女朋友答应25年底的时候见双方父母</strong>)，下定决心要做个改变，实习结束回到学校后，从2025年3月1日开始，踏上了我一个人的健身之路，此博客记录开始于2025年5月21日，这两个多月里已经将健身当成了习惯，每天下午五点，我都会像NPC一样出现在上海北路......</p><p><code>25年6月</code>本科毕业回老家后，和我的三个好兄弟组成<code>健身房龙级灾害——精灵团</code>,继续我们的健身之路......</p><h2 id="记录" tabindex="-1">记录 <a class="header-anchor" href="#记录" aria-label="Permalink to &quot;记录&quot;">​</a></h2><p><strong>1/3：胸肌 + 三头肌</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*10)</th><th>现在做组重量(4*10)</th><th>PR</th></tr></thead><tbody><tr><td>平板卧推</td><td>4</td><td>10</td><td>25kg</td><td>55kg</td><td>暂未尝试</td></tr><tr><td>上斜哑铃卧推</td><td>4</td><td>10</td><td>7.5kg</td><td>20kg</td><td>22.5kg</td></tr><tr><td>双杠臂屈伸</td><td>4</td><td>10</td><td>目前只能辅助臂屈伸</td><td></td><td></td></tr><tr><td>绳索下压</td><td>4</td><td>10</td><td>龙门架一片(没看过多重)</td><td>6片</td><td>暂未尝试</td></tr><tr><td>蝴蝶机夹胸</td><td>4</td><td>10</td><td>20kg</td><td>50kg</td><td>暂未尝试</td></tr></tbody></table><p><strong>2/3: 背 + 二头肌</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*10)</th><th>现在做组重量(4*10)</th><th>PR</th></tr></thead><tbody><tr><td>高位下拉</td><td>4</td><td>10</td><td>27kg</td><td>47.5kg</td><td>暂未尝试</td></tr><tr><td>俯身器械划船</td><td>4</td><td>10</td><td>10kg</td><td>30kg</td><td>32.5kg</td></tr><tr><td>坐姿划船</td><td>4</td><td>10</td><td>20kg</td><td>47.5g</td><td>暂未尝试</td></tr><tr><td>辅助引体</td><td>4</td><td>10</td><td>44kg</td><td>24kg</td><td>暂未尝试</td></tr><tr><td>杠铃弯举</td><td>4</td><td>10</td><td>10kg</td><td>20kg</td><td>暂未尝试</td></tr><tr><td>哑铃交替弯举</td><td>4</td><td>10</td><td>5kg</td><td>10kg</td><td>暂未尝试</td></tr></tbody></table><p><strong>3/3：肩 + 核心/腿</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*10)</th><th>现在做组重量(4*10)</th><th>PR</th></tr></thead><tbody><tr><td>坐姿哑铃推肩</td><td>4</td><td>10</td><td>7.5kg</td><td>20kg</td><td>暂未尝试</td></tr><tr><td>哑铃飞鸟</td><td>4(递减力竭组)</td><td>10</td><td>5kg</td><td>10kg</td><td>暂未尝试</td></tr><tr><td>侧平举</td><td>4</td><td>10</td><td>2.5kg</td><td>10kg</td><td>暂未尝试</td></tr><tr><td>前平举</td><td>4</td><td>10</td><td>2.5kg</td><td>5kg(真的难)</td><td>暂未尝试</td></tr><tr><td>绳索面拉</td><td>4</td><td>10</td><td>25kg</td><td>30kg</td><td>暂未尝试</td></tr><tr><td>仰卧起坐</td><td>4</td><td>15</td><td></td><td></td><td></td></tr><tr><td>龙门架卷腹</td><td>5</td><td>20</td><td>50kg</td><td>60kg</td><td></td></tr><tr><td>史密斯深蹲</td><td>4</td><td>8</td><td>60kg</td><td>60kg</td><td>暂未尝试</td></tr></tbody></table><hr><p><code>最后更新时间：2025-08-13 22:23:55</code></p>',13)]))}const l=d(h,[["render",o]]);export{i as __pageData,l as default};
